create table if not exists districts (id bigint generated by default as identity primary key, name text unique not null, macro_area text, municipality text default 'Milano', created_at timestamptz default now());
create table if not exists market_prices (id bigint generated by default as identity primary key, district_id bigint references districts(id) on delete cascade, asset_type text not null check (asset_type in ('room','apartment')), room_type text, euro_mq numeric, median_price numeric, min_price numeric, max_price numeric, source text, source_period text, updated_at timestamptz default now());
create table if not exists urban_quality_scores (id bigint generated by default as identity primary key, district_id bigint references districts(id) on delete cascade, green_score numeric, mobility_score numeric, services_score numeric, safety_proxy_score numeric, urban_quality_index numeric, source text, updated_at timestamptz default now());
create table if not exists mobility_scores (id bigint generated by default as identity primary key, district_id bigint references districts(id) on delete cascade, nearest_metro text, metro_lines text, mobility_score numeric, updated_at timestamptz default now());
create table if not exists listing_analyses (id bigint generated by default as identity primary key, listing_type text check (listing_type in ('room','apartment')), district_id bigint references districts(id), price numeric, size_mq numeric, room_type text, expenses_included boolean, score numeric, created_at timestamptz default now());
create or replace view district_engine_view as select d.id,d.name,d.macro_area,coalesce(ap.euro_mq,20) as euro_mq_apartment,coalesce(rm.median_price,700) as median_room_price,coalesce(ms.mobility_score,uq.mobility_score,7) as mobility_score,coalesce(uq.urban_quality_index,7) as urban_quality_index,coalesce(uq.services_score,7) as services_score,coalesce(uq.safety_proxy_score,7) as safety_proxy_score,coalesce(uq.green_score,7) as green_score,8 as youth_fit_score,7.5 as trend_score,coalesce(ms.nearest_metro,'Da verificare') as metro from districts d left join market_prices ap on ap.district_id=d.id and ap.asset_type='apartment' left join market_prices rm on rm.district_id=d.id and rm.asset_type='room' left join urban_quality_scores uq on uq.district_id=d.id left join mobility_scores ms on ms.district_id=d.id;